1	import { FrameScheduler } from "../../utils/FrameScheduler.js";
2	import type { LenisInstance, WindowWithLenis } from "../../types/app.types.js";
3	import {
4	  LENIS_SCROLL_CONFIG,
5	  LENIS_SCROLL_TRIGGER_SYNC_CONFIG,
6	} from "../../config/timeline.config.js";
7	
8	const LENIS_PREVENT_SELECTORS = [
9	  "[data-lenis-prevent]",
10	  "[data-lenis-prevent-wheel]",
11	  "[data-lenis-prevent-touch]",
12	].join(", ");
13	
14	export class LenisRuntime {
15	  private instance: LenisInstance | null = null;
16	  private rafId: number | null = null;
17	  private nativeScrollRafId: number | null = null;
18	  private lastScrollY = 0;
19	  private settleFramesLeft = 0;
20	  private isScrollbarDragSyncEnabled = false;
21	  private _initialized = false;
22	  private _disposed = false;
23	  private _pageshowListenerAttached = false;
24	  private readonly _pageshowHandler = (e: PageTransitionEvent): void => {
25	    if (!e.persisted) return;
26	    if (!this.instance) return;
27	    // bfcache 복원: Lenis RAF 체인이 끊김 → 취소 후 재시작
28	    if (this.rafId !== null) {
29	      FrameScheduler.cancel(this.rafId);
30	      this.rafId = null;
31	    }
32	    const onRaf = (time: number): void => {
33	      this.instance?.raf(time);
34	      this._syncScrollTrigger();
35	      this.rafId = FrameScheduler.request(onRaf);
36	    };
37	    this.rafId = FrameScheduler.request(onRaf);
38	  };
39	  private readonly _onPointerDown = (event: PointerEvent): void => {
40	    this.isScrollbarDragSyncEnabled = this.isScrollbarPointerDown(event);
41	  };
42	  private readonly _onPointerUp = (): void => {
43	    this.isScrollbarDragSyncEnabled = false;
44	  };
45	  private readonly _onNativeScroll = (): void => {
46	    if (!this.instance) return;
47	    if (!this.isScrollbarDragSyncEnabled) return;
48	    if (this.nativeScrollRafId != null) return;
49	    this.nativeScrollRafId = window.requestAnimationFrame(() => {
50	      this.nativeScrollRafId = null;
51	      const currentScrollY = window.scrollY ?? window.pageYOffset ?? 0;
52	      const lenisScroll =
53	        this.instance?.actualScroll ??
54	        this.instance?.animatedScroll ??
55	        currentScrollY;
56	      if (
57	        Math.abs(currentScrollY - lenisScroll) <
58	        LENIS_SCROLL_TRIGGER_SYNC_CONFIG.minDeltaPx
59	      ) {
60	        return;
61	      }
62	      this.instance?.scrollTo?.(currentScrollY, { immediate: true });
63	      this.lastScrollY = currentScrollY;
64	      this.settleFramesLeft = LENIS_SCROLL_TRIGGER_SYNC_CONFIG.settleFrames;
65	      window.ScrollTrigger?.update?.();
66	    });
67	  };
68	
69	  async init(): Promise<void> {
70	    if (this._initialized || this._disposed) return;
71	    this.onInit();
72	    this._initialized = true;
73	  }
74	
75	  dispose(): void {
76	    if (this._disposed) return;
77	    this._disposed = true;
78	    this._initialized = false;
79	    this.onDispose();
80	  }
81	
82	  private onInit(): void {
83	    if (this.instance) return;
84	
85	    const LenisCtor = this.resolveLenisCtor();
86	    if (!LenisCtor) return;
87	
88	    this.instance = new LenisCtor({
89	      autoRaf: false,
90	      smoothWheel: true,
91	      lerp: LENIS_SCROLL_CONFIG.lerp,
92	      wheelMultiplier: LENIS_SCROLL_CONFIG.wheelMultiplier,
93	      touchMultiplier: LENIS_SCROLL_CONFIG.touchMultiplier,
94	      prevent: (node: Element) => this.shouldPreventLenis(node),
95	    });
96	    (window as WindowWithLenis).__appLenis = this.instance;
97	    this.lastScrollY = window.scrollY ?? window.pageYOffset ?? 0;
98	    this.settleFramesLeft = LENIS_SCROLL_TRIGGER_SYNC_CONFIG.settleFrames;
99	
100	    const onRaf = (time: number): void => {
101	      this.instance?.raf(time);
102	      this._syncScrollTrigger();
103	      this.rafId = FrameScheduler.request(onRaf);
104	    };
105	    this.rafId = FrameScheduler.request(onRaf);
106	    window.addEventListener("scroll", this._onNativeScroll, { passive: true });
107	    window.addEventListener("pointerdown", this._onPointerDown, {
108	      passive: true,
109	    });
110	    window.addEventListener("pointerup", this._onPointerUp, {
111	      passive: true,
112	    });
113	    window.addEventListener("pointercancel", this._onPointerUp, {
114	      passive: true,
115	    });
116	    if (!this._pageshowListenerAttached) {
117	      window.addEventListener("pageshow", this._pageshowHandler);
118	      this._pageshowListenerAttached = true;
119	    }
120	  }
121	
122	  private onDispose(): void {
123	    if (this.rafId !== null) {
124	      FrameScheduler.cancel(this.rafId);
125	      this.rafId = null;
126	    }
127	    if (this.nativeScrollRafId !== null) {
128	      window.cancelAnimationFrame(this.nativeScrollRafId);
129	      this.nativeScrollRafId = null;
130	    }
131	    window.removeEventListener("scroll", this._onNativeScroll);
132	    window.removeEventListener("pointerdown", this._onPointerDown);
133	    window.removeEventListener("pointerup", this._onPointerUp);
134	    window.removeEventListener("pointercancel", this._onPointerUp);
135	    this.instance?.destroy?.();
136	    this.instance = null;
137	    this.settleFramesLeft = 0;
138	    this.isScrollbarDragSyncEnabled = false;
139	    delete (window as WindowWithLenis).__appLenis;
140	    if (this._pageshowListenerAttached) {
141	      window.removeEventListener("pageshow", this._pageshowHandler);
142	      this._pageshowListenerAttached = false;
143	    }
144	  }
145	
146	  private _syncScrollTrigger(): void {
147	    const currentScrollY = window.scrollY ?? window.pageYOffset ?? 0;
148	    const moved =
149	      Math.abs(currentScrollY - this.lastScrollY) >=
150	      LENIS_SCROLL_TRIGGER_SYNC_CONFIG.minDeltaPx;
151	    if (moved) {
152	      this.lastScrollY = currentScrollY;
153	      this.settleFramesLeft = LENIS_SCROLL_TRIGGER_SYNC_CONFIG.settleFrames;
154	      window.ScrollTrigger?.update?.();
155	      return;
156	    }
157	    if (this.settleFramesLeft <= 0) return;
158	    this.settleFramesLeft -= 1;
159	    window.ScrollTrigger?.update?.();
160	  }
161	
162	  private resolveLenisCtor(): WindowWithLenis["Lenis"] {
163	    return (window as WindowWithLenis).Lenis;
164	  }
165	
166	  private shouldPreventLenis(node: Element): boolean {
167	    if (!(node instanceof Element)) return false;
168	    if (node.closest(LENIS_PREVENT_SELECTORS) != null) return true;
169	    const rootNode = node.getRootNode();
170	    if (!(rootNode instanceof ShadowRoot)) return false;
171	    const host = rootNode.host;
172	    if (!(host instanceof Element)) return false;
173	    return host.matches(LENIS_PREVENT_SELECTORS) || host.closest(LENIS_PREVENT_SELECTORS) != null;
174	  }
175	
176	  private isScrollbarPointerDown(event: PointerEvent): boolean {
177	    const root = document.documentElement;
178	    const hasVerticalScrollbar = root.scrollHeight > root.clientHeight;
179	    if (hasVerticalScrollbar && event.clientX >= root.clientWidth) {
180	      return true;
181	    }
182	    const hasHorizontalScrollbar = root.scrollWidth > root.clientWidth;
183	    if (hasHorizontalScrollbar && event.clientY >= root.clientHeight) {
184	      return true;
185	    }
186	    return false;
187	  }
188	}
