744	      titlePeakScale,
745	      MAIN_WHY_SHOWCASE.titleScaleEnd,
746	      scatterProgress,
747	    );
748	    const titleY = Helpers.lerp(
749	      MAIN_WHY_SHOWCASE.titleYOffsetPx,
750	      0,
751	      spawnProgress,
752	    ) + Helpers.lerp(0, MAIN_WHY_SHOWCASE.titleExitYOffsetPx, scatterProgress);
753	
754	    const titleTransform = `translate3d(0, ${titleY}px, 0) scale(${titleScale})`;
755	    titleLayers.forEach((titleLayer) => {
756	      titleLayer.style.opacity = String(titleOpacity);
757	      titleLayer.style.transform = titleTransform;
758	    });
759	
760	    const ringOpacity =
761	      MAIN_WHY_SHOWCASE.ringOpacityMax * Math.max(spawnProgress, mergeProgress);
762	    const ringScale = Helpers.lerp(
763	      MAIN_WHY_SHOWCASE.ringScaleStart,
764	      MAIN_WHY_SHOWCASE.ringScaleEnd,
765	      Math.max(spawnProgress, scatterProgress),
766	    );
767	    ring.style.opacity = String(ringOpacity);
768	    ring.style.transform = `translate3d(-50%, -50%, 0) scale(${ringScale})`;
769	
770	    cards.forEach((card, index) => {
771	      const pose = MAIN_WHY_SHOWCASE.cardPoses[index];
772	      if (!pose) return;
773	      const revealStart =
774	        Helpers.lerp(
775	          MAIN_WHY_SHOWCASE.cardRevealWindowStart,
776	          MAIN_WHY_SHOWCASE.cardRevealWindowEnd,
777	          index / cardCount,
778	        );
779	      const revealEnd =
780	        Helpers.lerp(
781	          MAIN_WHY_SHOWCASE.cardRevealWindowStart,
782	          MAIN_WHY_SHOWCASE.cardRevealWindowEnd,
783	          (index + 1) / cardCount,
784	        );
785	      const cardRevealProgress = this._easeOutCubic(
786	        Helpers.remap01(progress, revealStart, revealEnd),
787	      );
788	      const orbitX =
789	        Math.cos(Helpers.degToRad(pose.orbitAngleDeg)) * pose.orbitRadiusVmin;
790	      const orbitY =
791	        Math.sin(Helpers.degToRad(pose.orbitAngleDeg)) *
792	        pose.orbitRadiusVmin *
793	        MAIN_WHY_SHOWCASE.orbitVerticalScale;
794	      const orbitRotate = pose.orbitRotateDeg;
795	      const revealScale =
796	        pose.scale *
797	        this._easeOutBack(
798	          cardRevealProgress,
799	          MAIN_WHY_SHOWCASE.cardRevealOvershoot,
800	        );
801	
802	      const mergedX = Helpers.lerp(orbitX, pose.stackXvmin, mergeProgress);
803	      const mergedY = Helpers.lerp(orbitY, pose.stackYvmin, mergeProgress);
804	      const mergedRotate = Helpers.lerp(
805	        orbitRotate,
806	        pose.stackRotateDeg,
807	        mergeProgress,
808	      );
809	      const mergedScale = Helpers.lerp(
810	        revealScale,
811	        pose.scale * MAIN_WHY_SHOWCASE.cardMergeScaleFactor,
812	        mergeProgress,
813	      );
814	
815	      const x = Helpers.lerp(mergedX, pose.scatterXvmin, scatterProgress);
816	      const y = Helpers.lerp(mergedY, pose.scatterYvmin, scatterProgress);
817	      const rotate = Helpers.lerp(
818	        mergedRotate,
819	        pose.scatterRotateDeg,
820	        scatterProgress,
821	      );
822	      const scale = Helpers.lerp(
823	        mergedScale,
824	        pose.scale * MAIN_WHY_SHOWCASE.cardScatterScaleFactor,
825	        scatterProgress,
826	      );
827	      const opacity = Helpers.lerp(
828	        Helpers.lerp(
829	          MAIN_WHY_SHOWCASE.cardOpacityStart,
830	          MAIN_WHY_SHOWCASE.cardOpacityEnd,
831	          cardRevealProgress,
832	        ),
833	        MAIN_WHY_SHOWCASE.cardScatterOpacity,
834	        scatterProgress,
835	      );
836	
837	      card.style.setProperty("--about-who-card-x", `${x}vmin`);
838	      card.style.setProperty("--about-who-card-y", `${y}vmin`);
839	      card.style.setProperty("--about-who-card-rotate", `${rotate}deg`);
840	      card.style.setProperty("--about-who-card-scale", String(scale));
841	      card.style.setProperty("--about-who-card-opacity", String(opacity));
842	      card.style.setProperty("--about-who-card-z", String(pose.zIndex));
843	    });
844	  }
