846	  private _easeOutCubic(value: number): number {
847	    const clampedValue = Helpers.clamp01(value);
848	    return 1 - Math.pow(1 - clampedValue, 3);
849	  }
850	
851	  private _easeOutBack(value: number, overshoot: number): number {
852	    const clampedValue = Helpers.clamp01(value);
853	    const nextValue = clampedValue - 1;
854	    return (
855	      1 +
856	      (overshoot + 1) * Math.pow(nextValue, 3) +
857	      overshoot * Math.pow(nextValue, 2)
858	    );
859	  }
860	
861	  private _easeInOutCubic(value: number): number {
862	    const clampedValue = Helpers.clamp01(value);
863	    if (clampedValue < 0.5) {
864	      return 4 * clampedValue * clampedValue * clampedValue;
865	    }
866	    const nextValue = -2 * clampedValue + 2;
867	    return 1 - Math.pow(nextValue, 3) / 2;
868	  }
