414	class WorksThumbnailRuntime {
415	  async warm(
416	    meshes: ReadonlyArray<THREE.Mesh>,
417	    placeholderImage: string,
418	    cardSize: WorkCardSize,
419	    log: (step: string, payload?: Record<string, unknown>) => void,
420	    onImageLoaded?: (mesh: THREE.Mesh, image: HTMLImageElement) => void,
421	  ): Promise<void> {
422	    let fallback: HTMLImageElement | null = null;
423	    const ensureFallback = async (): Promise<HTMLImageElement> => {
424	      if (!fallback) {
425	        fallback = await WorkCard.loadPlaceholderImage(placeholderImage);
426	      }
427	      return fallback;
428	    };
429	
430	    let index = 0;
431	    const batchSize = 4;
432	    const runBatch = async (): Promise<void> => {
433	      const end = Math.min(index + batchSize, meshes.length);
434	      const slice = meshes.slice(index, end);
435	      await Promise.all(
436	        slice.map(async (mesh) => {
437	          if (!mesh) return;
438	          const userData = mesh.userData as WorkCardUserData;
439	          const material = mesh.material as THREE.MeshBasicMaterial;
440	          const map = material.map;
441	          if (!map || !(map instanceof THREE.CanvasTexture)) return;
442	          const thumb = userData.proj.thumbnailImage?.trim() ?? "";
443	          let img: HTMLImageElement;
444	          if (thumb) {
445	            try {
446	              img = await WorkCard.loadImage(thumb);
447	            } catch {
448	              img = await ensureFallback();
449	            }
450	          } else {
451	            img = await ensureFallback();
452	          }
453	          WorkCard.updateTextureImage(
454	            map,
455	            userData.proj,
456	            cardSize,
457	            img,
458	            SCATTER_CARD_RENDER_OPTIONS,
459	          );
460	          onImageLoaded?.(mesh, img);
461	        }),
462	      );
463	      index = end;
464	      log("warmThumbnails.batch", { updatedUntil: index, total: meshes.length });
465	      if (index < meshes.length) {
466	        FrameScheduler.request(() => {
467	          void runBatch();
468	        });
469	      }
470	    };
471	    void runBatch();
472	  }
473	}
