6	export class PinnedRevealRuntime {
7	  private readonly _entries = new Set<PinnedRevealEntry>();
8	
9	  init(configs: readonly PinnedRevealConfig[]): void {
10	    this.dispose();
11	    if (typeof document === "undefined") return;
12	    if (configs.length === 0) return;
13	
14	    const win = window as WindowWithGsap;
15	    const gsap = win.gsap;
16	    const ScrollTrigger = win.ScrollTrigger;
17	    if (!gsap || !ScrollTrigger) return;
18	
19	    configs.forEach((config) => {
20	      const section = document.querySelector<HTMLElement>(
21	        config.sectionSelector,
22	      );
23	      const target = document.querySelector<HTMLElement>(config.targetSelector);
24	      if (!section || !target) return;
25	
26	      gsap.killTweensOf?.(target);
27	      const timeline = gsap.timeline({ paused: true });
28	      gsap.set(target, {
29	        autoAlpha: config.animation.fromAutoAlpha,
30	        y: config.animation.fromY,
31	      });
32	
33	      timeline.fromTo(
34	        target,
35	        {
36	          autoAlpha: config.animation.fromAutoAlpha,
37	          y: config.animation.fromY,
38	        },
39	        {
40	          autoAlpha: 1,
41	          y: 0,
42	          duration: config.animation.duration,
43	          ease: config.animation.ease,
44	          immediateRender: false,
45	        },
46	      );
47	
48	      if (config.exitAnimation) {
49	        timeline.to(target, {
50	          autoAlpha: config.exitAnimation.toAutoAlpha,
51	          y: config.exitAnimation.toY,
52	          duration: config.exitAnimation.duration,
53	          ease: config.exitAnimation.ease,
54	          immediateRender: false,
55	        });
56	      }
57	
58	      const trigger = ScrollTrigger.create({
59	        trigger: section,
60	        start: config.start,
61	        end: this._resolveEnd(config.end, section),
62	        scrub: config.scrub,
63	        pin: target,
64	        pinSpacing: config.pinSpacing,
65	        animation: timeline,
66	        invalidateOnRefresh: true,
67	        immediateRender: false,
68	      });
69	
70	      this._entries.add({ target, timeline, trigger });
71	    });
